    ...ex,
    averageRestSeconds: ex.averageRestSeconds ?? (ex.type === "B\xE1sico" ? 120 : ex.type === "Aislamiento" ? 60 : 90),
    coreInvolvement: ex.coreInvolvement ?? (hasCore ? isCompound ? "high" : "medium" : "low"),
